// Haiku: aggressive predictive targeting with strategic evasion
// Stats: armor 2, engine 3, gun 3, reload 2
// Better bullets + mobility, trades armor for firepower

const norm = (a) => Math.atan2(Math.sin(a), Math.cos(a));
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

// Simple threat detection: find incoming bullets heading toward us
function findThreat(me, bullets) {
  let bestThreat = null;
  let bestTime = Infinity;

  for (const b of bullets) {
    // Ignore our own bullets unless they bounced
    if (b.mine && !b.canHitOwner) continue;

    const dx = me.x - b.x;
    const dy = me.y - b.y;
    const v2 = b.vx * b.vx + b.vy * b.vy;
    if (v2 < 1) continue;

    const dot = dx * b.vx + dy * b.vy;
    const t = dot / v2;

    // Only care about bullets coming at us in the near future
    if (t < 0.05 || t > 0.6) continue;

    const closestX = b.x + b.vx * t;
    const closestY = b.y + b.vy * t;
    const miss = Math.hypot(closestX - me.x, closestY - me.y);

    if (miss < 50 && t < bestTime) {
      bestTime = t;
      bestThreat = { b, t, miss, dx: closestX - me.x, dy: closestY - me.y };
    }
  }

  return bestThreat;
}

// Predict where enemy will be when our bullet reaches it
function predictTargetPosition(me, enemy) {
  const bulletSpeed = me.stats.bulletSpeed;
  let px = enemy.x;
  let py = enemy.y;

  // Iterative refinement: where enemy will be when bullet travels there
  for (let i = 0; i < 3; i++) {
    const dist = Math.hypot(px - me.x, py - me.y);
    const travelTime = dist / bulletSpeed;
    px = enemy.x + enemy.vx * travelTime;
    py = enemy.y + enemy.vy * travelTime;
  }

  return { x: px, y: py };
}

// Check if we can see the enemy (rough line-of-sight)
function hasLineOfSight(me, enemy, walls) {
  for (const w of walls) {
    const dx = enemy.x - me.x;
    const dy = enemy.y - me.y;
    if (Math.abs(dx) < 1 && Math.abs(dy) < 1) return true;

    const wMinX = w.x - 40;
    const wMaxX = w.x + w.w + 40;
    const wMinY = w.y - 40;
    const wMaxY = w.y + w.h + 40;

    let t0 = 0, t1 = 1;
    const clip = (p, q) => {
      if (Math.abs(p) < 1e-9) return q >= 0;
      const t = q / p;
      if (p < 0) { if (t > t1) return false; if (t > t0) t0 = t; }
      else { if (t < t0) return false; if (t < t1) t1 = t; }
      return true;
    };

    if (!clip(-dx, me.x - wMinX) || !clip(dx, wMaxX - me.x) ||
        !clip(-dy, me.y - wMinY) || !clip(dy, wMaxY - me.y)) {
      continue; // Line passes outside this wall's padding
    }

    // If we get here, line intersects this wall
    if (t0 < t1 && t0 > 0 && t1 < 1) return false; // Wall blocks line
  }
  return true;
}

// Drive toward a waypoint
function driveToward(me, targetX, targetY, reverse = false) {
  const wantAngle = Math.atan2(targetY - me.y, targetX - me.x);
  const headingDiff = norm(wantAngle - me.heading);

  if (reverse) {
    // Back up toward target
    return {
      throttle: -0.8,
      turn: clamp(headingDiff * 2.5, -1, 1)
    };
  }

  // If target is behind us, consider turning around
  if (Math.abs(headingDiff) > 2.0) {
    return {
      throttle: 0,
      turn: clamp(headingDiff * 2.5, -1, 1)
    };
  }

  return {
    throttle: Math.cos(headingDiff) > 0.3 ? 0.9 : 0.3,
    turn: clamp(headingDiff * 3, -1, 1)
  };
}

// Dodge a bullet
function dodgeBullet(me, threat, enemy) {
  // Move perpendicular to bullet's direction
  const perpAngle = Math.atan2(threat.b.vy, threat.b.vx) + Math.PI / 2;
  const side = threat.dy * Math.cos(perpAngle) + threat.dx * Math.sin(perpAngle) > 0 ? 1 : -1;

  // Dodge in perpendicular direction
  const dodgeX = me.x + Math.cos(perpAngle) * 100 * side;
  const dodgeY = me.y + Math.sin(perpAngle) * 100 * side;

  return driveToward(me, dodgeX, dodgeY);
}

export default {
  name: 'Хаику',
  motto: 'Мишень в движенье — выстрел не спешит',
  stats: { armor: 2, engine: 3, gun: 3, reload: 2 },

  init(info) {
    // Initialization per round if needed
  },

  tick(state) {
    const { me, enemy, arena, bullets, repairKits, zone, time } = state;

    // ==================== TURRET ====================
    // Aim at predicted enemy position
    const pred = predictTargetPosition(me, enemy);
    const aimAngle = Math.atan2(pred.y - me.y, pred.x - me.x);
    const turretDiff = norm(aimAngle - me.turret);
    const turretTurn = clamp(turretDiff * 7, -1, 1);

    // Fire when aimed close enough and enemy is alive
    const fireReady = me.reloadLeft <= 0 && enemy.alive;
    const aimed = Math.abs(turretDiff) < 0.08;
    const los = hasLineOfSight(me, enemy, arena.walls);
    const fire = fireReady && aimed && los;

    // ==================== HULL ====================
    let drive;

    // Priority 1: Dodge incoming threats
    const threat = findThreat(me, bullets);
    if (threat && threat.t < 0.3) {
      drive = dodgeBullet(me, threat, enemy);
    } else {
      // Priority 2: Check zone shrink and health
      const distToZoneEdge = Math.hypot(me.x - zone.x, me.y - zone.y) - zone.radius;

